insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7dc61f4a-f296-4e9b-ae8f-01bd4a923b88', 'fr', 'Quels signes montrent qu’elle t’imite peut-être ?', '["Elle prend une posture semblable après que tu as changé la tienne", "Elle s’accorde à ton débit de parole", "Elle pose plus de questions", "Elle oriente son corps vers toi"]'::jsonb, 'Un accord physique et énergétique indique souvent de l’aisance et de l’implication.')
