insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('525d7416-b2f1-4458-807f-26c8a8bd7bc8', 'fr', 'Quel est le but principal du toucher quand tu flirtes ?', '["Aller le plus vite possible plus loin physiquement", "Tester ses limites", "Renforcer un lien émotionnel déjà là", "Remplacer la conversation"]'::jsonb, 'Le toucher marche quand il soutient une complicité qui existe déjà, pas quand il essaie de la créer.')
