insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5136a469-f474-4b76-bc20-841071ccf772', 'fr', 'Elle reste impliquée dans la conversation, mais ne rend jamais le toucher et ne l’accueille pas. Que dois-tu faire ?', '["Toucher davantage pour faire tomber sa résistance", "Lui demander directement pourquoi elle ne réagit pas", "Arrêter le toucher et rester dans l’échange verbal", "Mettre fin tout de suite à l’échange"]'::jsonb, 'Si elle ne rend pas le contact, le toucher n’est pas encore bienvenu. Ajuste-toi sans forcer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('efe69dc3-5d6a-4f17-b046-2263cec2230f', 'fr', 'Quels moments sont appropriés pour un toucher léger ?', '["Quand elle se penche vers toi ou reste proche", "Quand elle donne des réponses courtes et polies", "Quand vous vous déplacez ensemble dans un lieu"]'::jsonb, 'Le toucher doit suivre son ouverture et un élan partagé, pas la neutralité ou le désintérêt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('249a63f3-79dc-45b1-b433-50465a7a107d', 'fr', 'Pourquoi ne pas être impressionné d’emblée renverse-t-il la dynamique habituelle du flirt ?', '["Ça montre que tu ne lui cours pas après et que tu ne surinvestis pas", "Ça montre que tu as tes propres exigences", "Ça crée un équilibre au lieu d’une poursuite à sens unique", "Toutes les réponses ci-dessus"]'::jsonb, 'On passe d’une situation où elle attend ton approbation à une sélection mutuelle.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('95ad96b3-d2ef-411c-b521-ec1a1bc7d496', 'fr', 'Elle raconte qu’on la reconnaît souvent grâce à Instagram. Qu’est-ce qui te permet de garder ta posture ?', '["« Incroyable, tu dois être super populaire. »", "« Je devrais te demander un autographe, alors ? »", "« Tu as combien d’abonnés ? »", "« Tu mérites toute cette attention. »"]'::jsonb, 'Une légère contradiction montre que tu n’es pas impressionné d’office, ce qui renverse la dynamique.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7440e677-e76b-4b16-a0f9-213ae82c821a', 'fr', 'Quelles phrases sont des exemples sains de « pas impressionné d’emblée » ?', '["« Il va falloir me convaincre. »", "« Ce n’est pas impressionnant. »", "« Je ne sais pas, je suis difficile à séduire. »", "« Tu n’as rien de spécial. »"]'::jsonb, 'Ne pas être impressionné, c’est la mettre légèrement au défi, jamais la rabaisser ni la mépriser.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a91f07b0-5946-49ce-804d-b862552b9592', 'fr', 'Qu’est-ce qui aide à créer de la tension sexuelle dans un échange ?', '["Les sujets profonds", "Une gentillesse claire et prévisible", "Rassurer sans arrêt", "Une ambiguïté sur tes intentions"]'::jsonb, 'La tension vient du possible. Quand l’intention est suggérée, pas déclarée, l’attention s’aiguise.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('93982613-1848-48bb-b22b-59bd8c12b62f', 'fr', 'Qu’est-ce qui aide à créer de la tension sexuelle ?', '["Soutenir son regard un instant de plus que ce qui est confortable", "Laisser durer un peu un contact sur son bras, si elle y prend clairement plaisir", "Te tenir un peu plus près, tant qu’elle reste détendue", "Toutes les réponses ci-dessus"]'::jsonb, 'La tension se construit par de petits moments voulus de proximité et de pause.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('67379ba9-deb9-45a2-b30c-f9b26b01536d', 'fr', 'Quelles phrases ont des chances de créer de la tension ?', '["« C’est un avis intéressant. »", "« J’essaie de ne pas te fixer, mais tu ne me facilites pas la tâche. »", "« Il y a une étincelle quand tu parles de ce que tu aimes. »", "« Pourquoi tu as choisi cette boisson ? »"]'::jsonb, 'Avouer avec humour qu’elle te fait de l’effet, ou remarquer une étincelle, suggère l’attirance sans être trop direct.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('43a061f7-1ccd-4592-8e5d-035717e37189', 'fr', 'Quel est le but principal d’un rappel ou d’une blague entre vous dans une conversation ?', '["Montrer ton intelligence et ta mémoire", "Relancer une conversation qui s’essouffle", "Créer une continuité et un lien partagé", "Répéter ce qu’elle a dit pour plus de clarté"]'::jsonb, 'Ils créent le sentiment d’une histoire commune : vous n’êtes plus des inconnus, vous êtes dans la confidence.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('344744cd-ace9-45d2-96db-317d056f2f2f', 'fr', 'Qu’est-ce qui rend les rappels efficaces ?', '["Rebondir sur un détail avec humour ou un détournement ludique", "Créer une continuité au lieu de sujets décousus", "Donner l’impression que la conversation se construit, au lieu de juste exister", "Toutes les réponses ci-dessus"]'::jsonb, 'Quand on se souvient de nous, on se sent vu, ce qui renforce l’aisance et le lien.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7a584c7b-29ae-4ef4-8faf-ee465bb72e66', 'fr', 'Quels moments font de bons rappels ou de bonnes blagues entre vous ?', '["Les petites blagues qu’elle a faites", "Les petites préférences ou manies qu’elle a mentionnées", "Les problèmes personnels", "Les avis légers ou les exagérations"]'::jsonb, 'Les rappels marchent le mieux avec des détails légers, ludiques ou qui disent qui elle est.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0395cf63-6575-4c9c-aaa2-83805005ade7', 'fr', 'Elle dit qu’elle est très forte pour deviner le signe astrologique des gens. Comment créer un petit défi amusant ?', '["Lui dire directement ton signe", "Dire que l’astrologie, ce n’est pas réel", "Lui demander sérieusement pourquoi elle y croit", "« Vas-y, devine le mien. »"]'::jsonb, 'Invite-la à deviner pour jouer, ce qui crée une tension partagée et de la répartie.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('061b4ffe-6aea-49da-b29e-1976fc8c62a3', 'fr', '« Tu prends quoi ? » ou « Je parie que je devine ce que tu vas prendre ». Laquelle crée le plus d’alchimie ?', '["La première : elle montre un vrai intérêt pour ses goûts", "La deuxième : le petit défi crée de l’implication et du jeu", "La première : elle crée mieux la complicité", "La deuxième : elle montre de l’assurance"]'::jsonb, 'Une devinette est un petit défi qui demande sa participation, ce qui crée de l’énergie.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0640bea3-7134-4d3d-bbd1-a2dd404d8c97', 'fr', 'Elle se rapproche en riant. Quelle est la meilleure réaction ?', '["Te figer pour ne pas mal interpréter", "Reculer pour rester prudent", "T’accorder calmement à sa proximité", "Changer de sujet"]'::jsonb, 'T’accorder à son mouvement garde l’échange en phase et confortable.')
