insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0dcb3ce2-da4e-48c3-8c5b-7ded4177d531', 'fr', 'Elle te taquine à son tour sur ta cuisine catastrophique. Que pourrais-tu faire ensuite ?', '["Te mettre sur la défensive et te justifier", "Changer vite de sujet", "Rire et rebondir sur sa taquinerie pour jouer", "La taquiner plus sérieusement"]'::jsonb, 'Jouer dans les deux sens montre ta sérénité et crée de l’alchimie.')
