insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0f0fa46d-8699-4a6c-9b7b-2fe8afa91fe5', 'fr', 'Elle décrit avec enthousiasme sa passion inhabituelle. Quel compliment est le meilleur ?', '["« Tu es unique. »", "« J’aime bien à quel point tu es passionnée par ça, ça se voit vraiment. »", "« Tu as des centres d’intérêt sympas. »", "« Tu es attirante quand tu t’enthousiasmes. »"]'::jsonb, 'Il porte précisément sur la façon dont elle vit son choix, ce qui montre que son énergie compte pour toi.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('14f120e4-9b66-4b46-81d5-b125235fb2f5', 'fr', 'En quoi la tension sexuelle diffère-t-elle d’une conversation amicale ?', '["Elle repose sur des sujets sérieux et des confidences profondes", "Elle évite tout signal non verbal et toute pause", "Elle introduit une légère incertitude sur les intentions", "Elle garde une dynamique totalement prévisible"]'::jsonb, 'L’étincelle vient du fait de suggérer plus, sans tout rendre clair.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('17429248-a6f9-42cf-a924-9553dec0b010', 'fr', 'Qu’est-ce qui fait passer les mêmes mots de gentils à séducteurs ?', '["Un rythme plus lent et une voix plus douce", "Un débit rapide et un regard fuyant", "Soutenir son regard avec un sourire", "Laisser le moment respirer ensuite"]'::jsonb, 'La présence et le moment ajoutent de l’intensité sans changer le contenu.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1bcaa8b7-9201-4ec7-bab9-cd622fb9b421', 'fr', 'Quelles phrases ont des chances de créer de la tension ?', '["« Tu dégages quelque chose de calme, j’aime bien »", "« C’est intéressant, raconte-moi. »", "« Et sinon, tu fais quoi dans la vie ? »", "« J’aime bien ta façon de soutenir le regard. »"]'::jsonb, 'Des observations sur sa présence ou sur l’attirance montrent ton intention sans la forcer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1e531297-8fe5-432d-9e8a-8bb1970f99ba', 'fr', 'Pourquoi un regard soutenu a-t-il un effet physiologique si puissant ?', '["Il montre naturellement une domination sociale", "Il libère de l’ocytocine, accélère le cœur et crée un sentiment d’intimité", "Il crée une vulnérabilité qui renforce le lien émotionnel"]'::jsonb, 'Le corps réagit d’abord au regard ; il augmente naturellement les signaux d’intimité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1e723f5c-f299-44f4-844c-f7190b8f4c42', 'fr', 'La discussion se passe bien, et elle soutient ton regard plus longtemps que d’habitude. Que dois-tu faire ?', '["Le rompre pour poser une question", "Le soutenir à ton tour avec un petit sourire et laisser le moment durer", "Détourner les yeux pour lui laisser de l’espace", "La fixer de façon exagérée pour aller vite plus loin"]'::jsonb, 'Répondre à un regard soutenu crée de l’intimité sans mots.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2bcd40a3-8939-4555-8f99-7c394079b7a0', 'fr', 'Pourquoi les compliments précis, qui portent sur ses choix, créent-ils un lien plus fort ?', '["Ils ressemblent à une vraie reconnaissance de ses efforts", "Ils montrent que tu as remarqué quelque chose qui dépend d’elle", "Ils jugent directement son apparence"]'::jsonb, 'Elle se sent vue pour ce qu’elle est, pas pour ce dont elle a hérité.')
