insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2d067124-8ee8-41b8-b580-f480159f861e', 'fr', 'Elle te regarde droit dans les yeux pendant une pause dans la conversation. Que dois-tu faire ?', '["Détourner vite le regard pour éviter la gêne", "La fixer intensément sans sourire", "Baisser les yeux et continuer à parler", "Sourire doucement et soutenir son regard calmement"]'::jsonb, 'Elle t’offre l’occasion d’un regard soutenu. Soutiens-le à ton tour, ne le romps pas par nervosité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2fc0d39c-22da-4308-8ee9-4ab4c88299d2', 'fr', 'Quelle croyance favorise le mieux un flirt respectueux ?', '["« Si je n’insiste pas, je vais rater des occasions »", "« Un refus veut dire que j’ai fait quelque chose de travers »", "« Avoir de l’assurance, c’est ne jamais reculer »", "« Toutes les rencontres ne sont pas faites pour continuer »"]'::jsonb, 'Le respect commence par accepter que le désintérêt est normal et n’est pas un échec personnel.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('34e3a8a0-43de-4673-af81-d73381d0ceba', 'fr', 'Elle dit qu’elle est très forte pour deviner d’où viennent les gens. Que pourrais-tu faire ensuite pour en faire un petit défi ?', '["Lui dire directement d’où tu viens", "La complimenter sur son talent", "L’interroger sérieusement sur ses voyages", "« Prouve-le : devine d’où je viens. »"]'::jsonb, 'Invite-la à deviner pour jouer, ce qui crée une implication mutuelle et de la taquinerie.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('36c3a4cc-1b9f-42ea-a62f-551942c80f5d', 'fr', 'Qu’est-ce qui rend un petit défi efficace quand tu flirtes ?', '["Un enjeu sans importance, qui se prête facilement à la répartie", "Un gros enjeu pour faire tes preuves", "Tester sérieusement ses connaissances", "Une personne qui gagne nettement"]'::jsonb, 'Un faible enjeu garde le jeu amusant, et quel que soit le résultat, il nourrit le lien.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('37dce606-feeb-4072-baf2-17e1f94a6f8e', 'fr', 'Elle fait une remarque fine sur les clients du café. Que pourrais-tu dire ensuite ?', '["« Tu as de jolis yeux. »", "« Tu es superbe aujourd’hui. »", "« Tu es drôle. »", "« Tu as une façon originale de le dire. Je ne l’avais pas remarqué. »"]'::jsonb, 'Ça porte directement sur son point de vue, et elle se sent vraiment vue.')
