insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('384c4054-61db-4bdb-b2c8-91998d08cbee', 'fr', 'Quels effets peut créer un regard soutenu ?', '["Un sentiment d’intimité plus fort", "Une excitation physiologique", "Un intérêt clairement communiqué", "Une pression sociale pour répondre par des mots"]'::jsonb, 'Le regard communique ton intérêt sans mots et sans forcer de réponse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('39d71381-3505-4e35-9880-fe45c1d756bb', 'fr', 'Pourquoi les rappels et les blagues entre vous renforcent-ils le lien dans une conversation ?', '["Ils créent un fil rien qu’à vous deux", "Ils montrent que tu écoutais vraiment", "Ils créent des références communes et de la familiarité", "Toutes les réponses ci-dessus"]'::jsonb, 'Les rappels transforment vite des inconnus en personnes qui ont une histoire commune.')
