insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3adb725c-dd19-430c-9522-0dfd8285559a', 'fr', 'Elle dit qu’elle est nulle en cuisine. Quelles réponses sont joueuses ?', '["« Tu manges des céréales le soir, alors ? »", "« Ce n’est pas grave, la cuisine, ce n’est pas pour tout le monde »", "« Dommage, moi, je cuisine beaucoup »", "« Nulle à quel point ? Tu arrives à faire brûler de l’eau ? »"]'::jsonb, 'La taquinerie marche quand elle reste légère et l’invite à répondre.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3cfd9dfa-fc1f-49af-862d-aea72f90adc9', 'fr', 'Elle gère un moment gênant avec élégance et humour. Que pourrais-tu dire ?', '["« Tu as super bien géré ça. »", "« Tu es parfaite. »", "« Tu as un très beau sourire. »", "« Ce n’était rien. »"]'::jsonb, 'Ça reconnaît son aisance sociale et le choix qu’elle a fait sur le moment.')
