insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('405b2702-ed84-4c3b-9a21-77729ea9f2d4', 'fr', 'Elle regarde le menu et dit : « Je réfléchis toujours trop. » Meilleure réponse culottée ?', '["« C’est assez courant. »", "« Tu hésites entre quoi et quoi ? »", "« Tu vas trouver. »", "« Ça se voit. C’est clairement une question de vie ou de mort. »"]'::jsonb, 'L’exagération, avec de la chaleur, crée de l’humour et du rythme sans chercher à impressionner.')
