insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('44e9bef3-c0f2-4d31-a3a2-481c50c7d9d5', 'fr', 'Quelles phrases ont des chances de créer de la tension ?', '["« C’est une histoire drôle. »", "« Parle-moi de ton travail. »", "« Il y a quelque chose dans ta façon de sourire… »", "« Tu dégages une énergie vraiment chaleureuse. »"]'::jsonb, 'Des observations douces sur son sourire ou son énergie suggèrent l’attirance et créent une légère intensité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('450fc086-463d-40c5-9ce4-77e9a664a8e7', 'fr', 'Elle dit : « Ce café est vraiment beaucoup trop cher. » Que pourrais-tu dire ensuite ?', '["« Oui, les prix sont fous partout. »", "« Tu devrais le faire chez toi. »", "« Mais toi, tu vaux clairement le café haut de gamme. »", "« Le tien a coûté combien ? »"]'::jsonb, 'Un compliment culotté glissé dans une blague crée une énergie de flirt.')
