insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4684c791-9598-4381-9511-739d9afdfead', 'fr', 'Quelles réactions montrent que ton humour a bien fonctionné ?', '["Elle rit sincèrement", "Elle te reprend pour jouer", "Elle fait des blagues à son tour", "Elle donne des réponses courtes et polies"]'::jsonb, 'L’implication et la réciprocité sont des feux verts. Des réponses courtes et polies, non.')
