insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4962a3a5-8566-4b58-aafd-36f4a302ce53', 'fr', 'Pourquoi rester trop loin pendant tout l’échange peut-il affaiblir l’attirance ?', '["Ça peut montrer un manque d’intérêt ou de l’incertitude", "Ça paraît impoli", "Ça l’embrouille", "Ça ralentit le rythme de la conversation"]'::jsonb, 'Tes mots peuvent montrer de l’intérêt, mais la distance traduit de l’hésitation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('49634200-5e42-4c7d-b10f-352eb5b017a0', 'fr', 'Pourquoi l’énergie compte-t-elle plus que les mots au début d’un flirt ?', '["Elle crée le ton émotionnel auquel on réagit en premier", "Une énergie chaleureuse et positive allège l’humeur des autres", "Une faible énergie montre toujours de l’assurance"]'::jsonb, 'On va vers des sensations positives et prenantes avant de s’intéresser au contenu.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
